CREATE TABLE concept_requests (user_id TEXT NOT NULL, space_id TEXT NOT NULL, request_id TEXT NOT NULL, document_id TEXT NOT NULL, location INTEGER NOT NULL CHECK(location BETWEEN 1 AND 50), state TEXT NOT NULL CHECK(state IN ('pending','ready','failed')), error TEXT, PRIMARY KEY(user_id,space_id), UNIQUE(user_id,request_id), FOREIGN KEY(user_id,space_id) REFERENCES material_imports(user_id,space_id) ON DELETE CASCADE);
CREATE TABLE concepts (user_id TEXT NOT NULL, space_id TEXT NOT NULL, id TEXT NOT NULL, request_id TEXT NOT NULL, title TEXT NOT NULL, label TEXT NOT NULL, description TEXT NOT NULL, selected INTEGER NOT NULL DEFAULT 1 CHECK(selected IN (0,1)), PRIMARY KEY(user_id,space_id,id), FOREIGN KEY(user_id,space_id) REFERENCES concept_requests(user_id,space_id) ON DELETE CASCADE);
CREATE TABLE concept_sources (user_id TEXT NOT NULL, space_id TEXT NOT NULL, concept_id TEXT NOT NULL, chunk_id TEXT NOT NULL, PRIMARY KEY(user_id,space_id,concept_id,chunk_id), FOREIGN KEY(user_id,space_id,concept_id) REFERENCES concepts(user_id,space_id,id) ON DELETE CASCADE, FOREIGN KEY(user_id,space_id,chunk_id) REFERENCES material_chunks(user_id,space_id,id) ON DELETE CASCADE);
CREATE TABLE concept_relations (user_id TEXT NOT NULL, space_id TEXT NOT NULL, from_id TEXT NOT NULL, to_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind='suggested'), PRIMARY KEY(user_id,space_id,from_id,to_id), FOREIGN KEY(user_id,space_id,from_id) REFERENCES concepts(user_id,space_id,id) ON DELETE CASCADE, FOREIGN KEY(user_id,space_id,to_id) REFERENCES concepts(user_id,space_id,id) ON DELETE CASCADE);
